// Find the inline 'Meetings' database on the client's CRM page
const blocks = $input.all().map(i => i.json);

const meetingsDb = blocks.find(b => {
  if (b.type !== 'child_database') return false;
  // Handle both simplified ('content') and full ('child_database.title') output shapes
  const title = (b.content || b.child_database?.title || '').toString().toLowerCase().trim();
  return title === 'meetings';
});

if (!meetingsDb) {
  throw new Error("No inline 'Meetings' database found. Available child_database titles: " +
    blocks.filter(b => b.type === 'child_database').map(b => b.content || b.child_database?.title).join(', ')
  );
}

return [{ json: { meetingsDbId: meetingsDb.id } }];

// Build Notion blocks from Fathom's webhook payload
const fathom = $('Fathom').first().json.body || {};

// Fathom's actual field paths
const summaryMd = (fathom.default_summary?.markdown_formatted || '').toString().trim();
const actionItems = Array.isArray(fathom.action_items) ? fathom.action_items : [];
const recordingUrl = fathom.share_url || fathom.url || '';
const meetingTitle = fathom.meeting_title || fathom.title || 'Meeting';
const startTime = fathom.scheduled_start_time || fathom.recording_start_time || '';

const meetingsDbId = $json.meetingsDbId;

function rt(content, opts = {}) {
  return {
    type: 'text',
    text: { content: content.slice(0, 1900), link: opts.link ? { url: opts.link } : null },
    annotations: {
      bold: !!opts.bold,
      italic: !!opts.italic,
      strikethrough: false,
      underline: false,
      code: false,
      color: 'default'
    }
  };
}

function paragraph(richTexts) {
  return { object: 'block', type: 'paragraph', paragraph: { rich_text: Array.isArray(richTexts) ? richTexts : [rt(richTexts)] } };
}

function heading(textOrRich, level = 2) {
  const key = `heading_${level}`;
  const richText = Array.isArray(textOrRich) ? textOrRich : parseInlineLinks(textOrRich);
  return { object: 'block', type: key, [key]: { rich_text: richText } };
}

function bullet(richTexts) {
  return { object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: Array.isArray(richTexts) ? richTexts : [rt(richTexts)] } };
}

function parseInlineLinks(line) {
  const out = [];
  // Match either [text](url) OR **text**
  const re = /\[([^\]]+)\]\(([^)]+)\)|\*\*([^*]+)\*\*/g;
  let last = 0, m;
  while ((m = re.exec(line)) !== null) {
    if (m.index > last) out.push(rt(line.slice(last, m.index)));
    if (m[1]) {
      // It's a link [text](url)
      out.push(rt(m[1], { link: m[2], bold: true }));
    } else if (m[3]) {
      // It's bold **text**
      out.push(rt(m[3], { bold: true }));
    }
    last = m.index + m[0].length;
  }
  if (last < line.length) out.push(rt(line.slice(last)));
  return out.length ? out : [rt(line)];
}

const blocks = [];

if (recordingUrl) {
  blocks.push({
    object: 'block',
    type: 'callout',
    callout: {
      icon: { type: 'emoji', emoji: '☎️' },
      rich_text: [
        rt(`${meetingTitle}: `),
        rt('Watch recording', { link: recordingUrl, bold: true })
      ]
    }
  });
}

if (summaryMd) {
  const lines = summaryMd.split(/\r?\n/);
  for (const raw of lines) {
    const line = raw.trim();
    if (!line) continue;
    if (line.startsWith('### ')) blocks.push(heading(line.replace(/^###\s+/, ''), 3));
    else if (line.startsWith('## ')) blocks.push(heading(line.replace(/^##\s+/, ''), 2));
    else if (line.startsWith('# ')) blocks.push(heading(line.replace(/^#\s+/, ''), 2));
    else if (/^[\*\-]\s+/.test(line)) blocks.push(bullet(parseInlineLinks(line.replace(/^[\*\-]\s+/, ''))));
    else blocks.push(paragraph(parseInlineLinks(line)));
  }
}

if (actionItems.length) {
  blocks.push(heading([rt('Action items')], 2));
  for (const a of actionItems) {
    const who = a.assignee?.name ? `${a.assignee.name}: ` : '';
    const desc = (a.description || '').trim();
    if (!desc) continue;
    blocks.push({
      object: 'block',
      type: 'to_do',
      to_do: {
        rich_text: [rt(`${who}${desc}`)],
        checked: !!a.completed
      }
    });
  }
}

const dt = startTime ? new Date(startTime) : new Date();
const isoDate = dt.toISOString().split('T')[0];

return [{
  json: {
    title: 'Meeting Summary',
    meetingDate: isoDate,
    meetingsDbId,
    blocks
  }
}];

