// Code node to combine Fathom transcript segments
// Place this node immediately after your Fathom webhook

// The webhook data comes in as $json.body
// The transcript array is at $json.body.transcript

const transcriptArray = $json.body.transcript || [];

// Combine all transcript segments into one continuous text
const fullTranscript = transcriptArray
  .map(segment => segment.text)
  .filter(text => text) // Remove any empty segments
  .join(' ');

// Optional: Also create a formatted version with speaker names and timestamps
const formattedTranscript = transcriptArray
  .map(segment => {
    const speaker = segment.speaker?.display_name || 'Unknown';
    const text = segment.text || '';
    const timestamp = segment.timestamp || '';
    return `[${timestamp}] ${speaker}: ${text}`;
  })
  .join('\n');

// Return both versions so you can use whichever you prefer
return {
  json: {
    fullTranscript: fullTranscript,
    formattedTranscript: formattedTranscript,
    transcriptLength: fullTranscript.length,
    segmentCount: transcriptArray.length
  }
};

// ===== SETUP: edit these so you are never matched as the client =====
const MY_EMAIL = 'YOUR_EMAIL';                 // the email your Fathom account records with
const MY_NAME = 'YOUR_NAME';                   // your name exactly as Fathom shows it in transcripts
const INTERNAL_DOMAIN = 'YOUR_COMPANY_DOMAIN'; // e.g. yourcompany.com, emails on it count as your team
// ======================================================================

// Resolve who the client is on this call.
// Path 1: the first external calendar invitee's email.
// Path 2: impromptu calls have no invitees, so also collect every
// speaker name from the transcript except yours, for a name match downstream.
const body = $('Fathom').first().json.body || {};
const invitees = body.calendar_invitees || [];
const recorder = body.recorded_by || {};
const recorderEmail = (recorder.email || MY_EMAIL).toLowerCase();
const recorderName = (recorder.name || MY_NAME).trim().toLowerCase();
const isInternal = e => !!INTERNAL_DOMAIN && e.toLowerCase().endsWith('@' + INTERNAL_DOMAIN.toLowerCase());

const ext = invitees.find(i => i.is_external);
const externalEmails = invitees
  .filter(i => i.email && i.email.toLowerCase() !== recorderEmail && (i.is_external || !isInternal(i.email)))
  .map(i => i.email.toLowerCase());

const talkShare = {};
for (const s of (body.transcript || [])) {
  const n = ((s.speaker || {}).display_name || '').trim();
  if (n) talkShare[n] = (talkShare[n] || 0) + 1;
}
const speakers = Object.keys(talkShare).filter(n => n.toLowerCase() !== recorderName);

return [{ json: {
  'Client email': ext ? ext.email : '__no_external_invitee__',
  externalEmails,
  speakers,
  talkShare,
  crmMatches: body.crm_matches || null,
  recordingId: body.recording_id || null,
  meetingTitle: body.meeting_title || body.title || 'Meeting',
  shareUrl: body.share_url || body.url || '',
  inviteeCount: invitees.length,
}}];

// Match the resolved client against every CRM row from Check CRM.
// Email match first (authoritative, may legitimately return several rows if the CRM has
// duplicates, same as the old filter). If no email match, fall back to transcript speaker
// names and require exactly ONE unambiguous CRM row. Anything else emits a _no_match item
// so the IF node routes it to a Slack alert instead of silently doing nothing.
const resolved = $('Set Client email').first().json;
const rows = $input.all().map(i => i.json);
const norm = s => (s || '').toString().trim().toLowerCase();
const tokens = s => norm(s).replace(/[^a-z\s]/g, ' ').split(/\s+/).filter(Boolean);
// Tie-breaks for the name path: the client is the non-host speaker who talks the most,
// then the row whose CRM status is the most active.
const talk = resolved.talkShare || {};
const STATUS_RANK = { 'on retainer': 5, 'in progress': 4, 'pitching': 3, 'meeting booked': 3, 'awaiting approval': 3, 'delivered': 2, 'dormant': 1 };
const statusRank = r => STATUS_RANK[norm(r.property_status)] || 0;

const emails = new Set([resolved['Client email'], ...(resolved.externalEmails || [])]
  .map(norm).filter(e => e && e !== '__no_external_invitee__'));
let matches = rows.filter(r => emails.has(norm(r.property_email)));
let method = 'email';
let candidates = [];

if (!matches.length && (resolved.speakers || []).length) {
  method = 'speaker-name';
  const scored = [];
  for (const r of rows) {
    const nameTokens = tokens(r.name);
    const rowTokens = new Set([...nameTokens, ...tokens(r.property_project_name)]);
    let best = 0, bestTalk = 0;
    for (const sp of resolved.speakers) {
      const st = tokens(sp);
      if (!st.length) continue;
      const first = st[0], last = st[st.length - 1];
      const hasFirst = rowTokens.has(first);
      const hasLast = st.length > 1 && rowTokens.has(last);
      let score = 0;
      if (hasFirst && hasLast) score = 3;                       // "Jane Smith" vs "Jane Smith"
      else if (hasFirst && nameTokens.length === 1) score = 2;  // "Jane Smith" vs CRM row "Jane"
      if (score > best || (score === best && (talk[sp] || 0) > bestTalk)) { best = score; bestTalk = talk[sp] || 0; }
    }
    if (best > 0) scored.push({ r, best, talk: bestTalk, status: statusRank(r) });
  }
  const top = scored.reduce((m, x) => Math.max(m, x.best), 0);
  let winners = scored.filter(x => x.best === top);
  if (winners.length > 1) {                                   // tie-break 1: who talked the most
    const maxTalk = Math.max(...winners.map(x => x.talk));
    const loud = winners.filter(x => x.talk === maxTalk);
    if (loud.length === 1 && maxTalk > 0) winners = loud;
    else if (loud.length > 1) {                               // tie-break 2: most active CRM status
      const maxStatus = Math.max(...loud.map(x => x.status));
      const active = loud.filter(x => x.status === maxStatus);
      if (active.length === 1) winners = active;
    }
  }
  candidates = scored.map(x => `${x.r.name} (score ${x.best}, segments ${x.talk}, ${x.r.property_status || 'no status'})`);
  if (winners.length === 1) matches = winners.map(x => x.r);
}

if (matches.length) {
  return matches.map(r => ({ json: { ...r, _match_method: method } }));
}

return [{ json: {
  _no_match: true,
  _reason: candidates.length > 1 ? 'ambiguous speaker-name match' : 'no email or speaker-name match',
  _candidates: candidates,
  _emails: [...emails],
  _speakers: resolved.speakers || [],
  _title: resolved.meetingTitle,
  _recordingId: resolved.recordingId,
  _shareUrl: resolved.shareUrl,
}}];

